using UnityEngine;
using UnityEngine.UI;
using JojoP.Gameplay.Brothers;
public static class McpBattleInfo {
  public static string Run() {
    var s = Object.FindFirstObjectByType<BrothersSessionController>();
    var b = s != null ? s.Battle : null;
    string flow = s != null ? s.Flow.ToString() : "no session";
    if (b == null) return flow + " no battle";
    return flow + " waveLeft=" + b.WaveLeft.ToString("0.0") + " bros=" + b.AliveBrothers + " enemies=" + b.AliveEnemies + " running=" + b.IsRunning;
  }
}
